package com.haucheng.erp.controller;
import com.haucheng.erp.auth.RequirePermission; import com.haucheng.erp.common.ApiResponse; import com.haucheng.erp.dto.BrandRequest; import com.haucheng.erp.entity.MdBrand; import com.haucheng.erp.service.BrandService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/master-data/brands") @RequiredArgsConstructor public class BrandController { private final BrandService service;
 @GetMapping @RequirePermission("system.brand.view") public ApiResponse<List<MdBrand>> list(){return ApiResponse.success(service.getAll());} @GetMapping("/options") @RequirePermission("system.product.view") public ApiResponse<List<MdBrand>> options(){return ApiResponse.success(service.getOptions());}
 @GetMapping("/{id}") @RequirePermission("system.brand.view") public ApiResponse<MdBrand> get(@PathVariable Long id){return ApiResponse.success(service.getById(id));} @PostMapping @RequirePermission("system.brand.create") public ApiResponse<MdBrand> create(@Valid @RequestBody BrandRequest r){return ApiResponse.success(service.create(r));} @PutMapping("/{id}") @RequirePermission("system.brand.update") public ApiResponse<MdBrand> update(@PathVariable Long id,@Valid @RequestBody BrandRequest r){return ApiResponse.success(service.update(id,r));}
 @PostMapping("/{id}/enable") @RequirePermission("system.brand.disable") public ApiResponse<Void> enable(@PathVariable Long id){service.updateStatus(id,true);return ApiResponse.success();} @PostMapping("/{id}/disable") @RequirePermission("system.brand.disable") public ApiResponse<Void> disable(@PathVariable Long id){service.updateStatus(id,false);return ApiResponse.success();} @DeleteMapping("/{id}") @RequirePermission("system.brand.delete") public ApiResponse<Void> delete(@PathVariable Long id){service.delete(id);return ApiResponse.success();}
}
